<template>
  <section class="teacher-page" data-testid="teacher-workbench-page">
    <div v-if="store.workbenchState === 'LOADING' || store.workbenchState === 'INITIAL'" class="state-panel"><span class="spinner" aria-hidden="true"></span><p>正在加载教师工作台...</p></div>
    <div v-else-if="store.workbenchState === 'FORBIDDEN' || store.workbenchState === 'ERROR'" class="state-panel state-panel--error"><h1>工作台暂时不可用</h1><p>{{ store.error ?? '请稍后重试。' }}</p><button type="button" @click="load">重新加载</button></div>
    <div v-else-if="!store.workbench?.currentStudent" class="state-panel"><h1>暂无当前教学对象</h1><p>当前没有 ACTIVE demo run，工作台将在真实教学对象进入后显示。</p><button type="button" @click="load">重新检查</button></div>
    <template v-else>
      <header class="page-heading"><div><p class="eyebrow">当前教学对象 / Golden Demo</p><h1>工作台</h1><p>围绕当前学生的学习证据推进下一步教学。</p></div><button class="outline-button" type="button" @click="router.push('/teacher/analytics')">进入数据洞察 <span aria-hidden="true">→</span></button></header>
      <section class="context-banner"><div class="avatar" aria-hidden="true">{{ student.displayName.slice(0, 1) }}</div><div class="context-copy"><span class="eyebrow">当前学生</span><h2>{{ student.displayName }}</h2><p>{{ student.courseName }} · {{ student.className }}</p></div><RouterLink class="text-link" :to="{ path: `/teacher/students/${encodeURIComponent(student.studentId)}`, query: { courseId: student.courseId } }">查看学生画像 <span aria-hidden="true">→</span></RouterLink></section>
      <section class="kpi-grid" aria-label="当前工作台事实"><article><span>优先事项</span><strong>{{ store.workbench.priorityItems.length }}</strong><small>当前学生</small></article><article><span>待审建议</span><strong>{{ store.workbench.pendingRecommendations.length }}</strong><small>真实分析记录</small></article><article><span>待记结果</span><strong>{{ store.workbench.pendingOutcomes.length }}</strong><small>已提交干预</small></article></section>
      <div class="workbench-grid">
        <main class="main-column">
          <section class="panel priority-panel"><header class="panel-heading"><div><span class="eyebrow">Action queue</span><h2>当前学习问题</h2></div><span class="panel-count">{{ store.workbench.priorityItems.length }} 项</span></header><div v-if="store.workbench.priorityItems.length" class="priority-list"><article v-for="item in store.workbench.priorityItems" :key="`${item.type}-${item.title}`" class="priority-item"><span class="priority-mark" :class="item.type.toLowerCase()" aria-hidden="true">{{ item.type === 'TEACHER_ASSIGNMENT' ? '任' : '学' }}</span><div><strong>{{ item.title }}</strong><p>{{ item.description }}</p><small v-if="item.knowledgePointName">知识点：{{ item.knowledgePointName }}</small></div><em>{{ statusLabel(item.status) }}</em></article></div><div v-else class="empty-inline">暂无优先事项</div></section>
          <section class="panel process-panel"><header class="panel-heading"><div><span class="eyebrow">Teaching process</span><h2>教学流程状态</h2></div></header><div class="process-steps"><div class="process-step is-current"><span>01</span><div><strong>识别学习问题</strong><small>已从学习快照与答题记录读取</small></div></div><div class="process-connector" aria-hidden="true"></div><div class="process-step" :class="{ 'is-current': store.workbench.pendingRecommendations.length > 0 }"><span>02</span><div><strong>查看分析建议</strong><small>{{ store.workbench.pendingRecommendations.length ? '有待教师复核的真实建议' : '暂无待复核建议' }}</small></div></div><div class="process-connector" aria-hidden="true"></div><div class="process-step" :class="{ 'is-current': store.workbench.pendingOutcomes.length > 0 }"><span>03</span><div><strong>跟进干预结果</strong><small>{{ store.workbench.pendingOutcomes.length ? '有待记录的干预结果' : '暂无待记录结果' }}</small></div></div></div></section>
        </main>
        <aside class="side-column"><section class="panel fact-panel"><header class="panel-heading"><div><span class="eyebrow">Learning evidence</span><h2>学习状态</h2></div></header><template v-if="profile?.learningState"><dl><div><dt>知识点</dt><dd>{{ profile.learningState.knowledgePointName }}</dd></div><div><dt>掌握度</dt><dd>{{ percent(profile.learningState.mastery) }}</dd></div><div><dt>置信度</dt><dd>{{ percent(profile.learningState.confidence) }}</dd></div><div><dt>遗忘风险</dt><dd>{{ percent(profile.learningState.forgettingRisk) }}</dd></div><div><dt>证据数</dt><dd>{{ profile.learningState.evidenceCount }} 条</dd></div></dl></template><p v-else class="empty-inline">暂无学习状态数据</p></section><section class="panel diagnosis-panel"><header class="panel-heading"><div><span class="eyebrow">Evidence summary</span><h2>诊断摘要</h2></div></header><template v-if="profile?.diagnosis"><p class="hypothesis">{{ profile.diagnosis.primaryHypothesis }}</p><div class="diagnosis-meta"><span :class="severityClass(profile.diagnosis.severity)">{{ severityLabel(profile.diagnosis.severity) }}</span><span>置信度 {{ percent(profile.diagnosis.confidence) }}</span></div><RouterLink v-if="student.demoCaseId" class="text-link" :to="`/teacher/diagnosis-cases/${encodeURIComponent(student.demoCaseId)}`">查看完整证据 <span aria-hidden="true">→</span></RouterLink></template><p v-else class="empty-inline">暂无可用诊断证据</p></section></aside>
      </div>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { useTeacherStore } from '@/stores/teacherStore'
const router = useRouter(); const store = useTeacherStore(); const student = computed(() => store.workbench!.currentStudent!); const profile = computed(() => store.profile)
const percent = (value: number) => `${Math.round(value * 100)}%`
const statusLabel = (value: string) => ({ PENDING_STUDENT: '待完成', IN_PROGRESS: '进行中', AVAILABLE: '待关注' }[value] ?? value)
const severityLabel = (value: string) => ({ HIGH: '高关注', MEDIUM: '中关注', LOW: '低关注' }[value] ?? '待评估')
const severityClass = (value: string) => `severity severity--${value.toLowerCase()}`
async function load() { await store.loadWorkbench(true); if (store.workbench?.currentStudent) await store.loadProfile(student.value.studentId, student.value.courseId, true) }
onMounted(() => void load())
</script>

<style scoped>
